/* ===== part 1 ===== */
(function(){
  var b=document.getElementById('boot'); if(!b) return;
  try{ if(sessionStorage.getItem('amanBoot2')){ b.parentNode.removeChild(b); return; } }catch(e){}
  var arc=b.querySelector('.ld-arc'), head=b.querySelector('.ld-head');
  var em=b.querySelector('.ld-embers');
  for(var k=0;k<16;k++){
    var e=document.createElement('i');
    e.style.cssText='--x:'+(Math.random()*100).toFixed(1)+'%;--s:'+(2+Math.random()*3).toFixed(1)+'px;--d:'+(5+Math.random()*5).toFixed(1)+'s;--w:-'+(Math.random()*8).toFixed(1)+'s;--dx:'+(Math.random()*120-60).toFixed(0)+'px';
    em.appendChild(e);
  }
  var num=document.getElementById('ldn'), msgs=b.querySelectorAll('.ld-st span'),
      loaded=document.readyState==='complete', closed=false, p=0, t0=Date.now(), MIN=1900, lastMsg=-1;
  function paint(){
    arc.style.strokeDashoffset=100-p;
    head.style.transform='rotate('+(p*3.6)+'deg)';
    head.style.opacity=p>=99.5?0:1;
    arc.classList.toggle('done',p>=100);
    num.textContent=Math.round(p);
    var m=p>=100?2:Math.min(2,Math.floor(p/34));
    if(m!==lastMsg){ for(var j=0;j<msgs.length;j++) msgs[j].className=j===m?'on':''; lastMsg=m; }
  }
  function close(){
    if(closed) return; closed=true;
    try{ sessionStorage.setItem('amanBoot2','1') }catch(e){}
    b.classList.add('out'); setTimeout(function(){ if(b.parentNode) b.parentNode.removeChild(b) },900);
  }
  function tick(){
    if(closed) return;
    var el=Date.now()-t0, ready=loaded&&el>=MIN;
    var goal=ready?100:Math.min(88,100*(1-Math.pow(1-Math.min(el/MIN,1),3)));
    p+=(goal-p)*(ready?.16:.12);
    if(goal-p<.4) p=goal;
    paint();
    if(p>=100){ setTimeout(function(){ b.classList.add('ready'); try{ enter.focus({preventScroll:true}) }catch(e){} },350); return; }
    requestAnimationFrame(tick);
  }
  var enter=document.getElementById('ldEnter'); enter.addEventListener('click',close);
  paint(); requestAnimationFrame(tick);
  if(!loaded) window.addEventListener('load',function(){ loaded=true; });
  setTimeout(function(){ loaded=true; },4000);   /* safety: Enter button always appears */
})();
;

/* ===== part 2 ===== */
(function(){
const $=id=>document.getElementById(id);
const input=$('number'),go=$('go'),goText=$('goText'),field=$('field'),preview=$('preview');
const res=$('res'),resIdle=$('resIdle'),resCode=$('resCode'),copyBtn=$('copyBtn'),regenBtn=$('regenBtn'),howto=$('howto');
const timer=$('timer'),timeLeft=$('timeLeft'),bar=$('bar'),barFill=$('barFill'),timerLabel=$('timerLabel'),RING=2*Math.PI*52,waiting=$('waiting'),success=$('success');
const srvBox=$('srvBox'),srvHead=$('srvHead'),srvGrid=$('srvGrid'),srvTitle=$('srvTitle'),srvSub=$('srvSub'),onlineTxt=$('onlineTxt'),srvNote=$('srvNote');
const DEFAULT_CC='92', LIFETIME=120;
let servers=[], selected=null, userPicked=false, currentCode='', countdown=null, poller=null, pollNumber='', pollBase='', lang='ur', busy=false, step=1;

/* ---------- text ---------- */
const EN={
  aboutTxt:'A fast WhatsApp bot you connect with a pairing code. Pick a server, enter your number, and you are set.',
  close:'Close', tool:'WhatsApp Pairing Tool',
  heroBig:'Connect your WhatsApp<br>Get pairing code',
  stServer:'Server', stNumber:'Number', stCode:'Code', tapChoose:'Tap to choose',
  lblNumber:'WhatsApp number',
  hint:'Include the country code. If you type 03XX, Pakistan (+92) is added for you.',
  idle:'Your pairing code will appear here', expires:'Code expires in',
  waiting:'Waiting for you to enter the code in WhatsApp... it will detect the connection automatically.',
  okTitle:'Bot connected!', okText:'Start using commands on your WhatsApp. Type',
  howTitle:'How to link on WhatsApp',
  s1:'Open WhatsApp and go to <em>Linked devices</em>.',
  s2:'Tap <em>Link a device</em>.',
  s3:'Choose <em>Link with phone number instead</em> and enter the code.',
  f1:'Song &amp; video download', f2:'Channel reacts &amp; follow',
  f3:'Islamic cartoons &amp; naat', f4:'Anime &amp; stickers',
  channel:'Channel', youtube:'YouTube',
  faqTitle:'Code not arriving or not working?',
  q1:'Use the number with country code, e.g. 923001234567.',
  q2:'Enter the code in WhatsApp within 2 minutes, or press <em>New code</em>.',
  q3:'Use the same number that is active on this phone.',
  q4:'If a server is full or offline, choose another one.'
};
const UR={}; document.querySelectorAll('[data-i]').forEach(e=>{UR[e.dataset.i]=e.innerHTML});
const T={ur:UR,en:EN};

const MSG={
 ur:{
   gen:'Generate Pairing Code', busy:'Code ban raha hai...', copy:'Copy pairing code', copied:'✓ Code copied',
   regen:'↻ Naya code', pick:'Server chunein', selSub:'Select a server',
   needNum:'Apna WhatsApp number likhein.',
   badLen:'Number 8 se 15 digits ka hona chahiye, country code ke saath.',
   expired:'Code expire ho gaya',
   conn:'Server se connect nahi hua. Doosra server chunein ya dobara try karein.',
   progress:'Connection chal raha hai, thodi der ruk kar dobara try karein.',
   reconn:'Is number ka session pehle se hai, reconnect ho raha hai.',
   wait:'Pair code generate ho raha hai...', manual:'Code ko manually select karein',
   generic:'Kuch galat hua. Thori der baad dobara try karein.',
   preview:'Pair hoga:', full:'FULL', off:'OFFLINE', free:'free', linked:'linked accounts',
   auto:'Sab se khali server khud chun liya gaya', none:'Koi server online nahi'
 },
 en:{
   gen:'Generate Pairing Code', busy:'Generating code...', copy:'Copy pairing code', copied:'✓ Code copied',
   regen:'↻ New code', pick:'Select a server', selSub:'Select a server',
   needNum:'Please enter your WhatsApp number.',
   badLen:'Number must be 8 to 15 digits including the country code.',
   expired:'Code expired',
   conn:'Could not reach the server. Pick another server or try again.',
   progress:'A connection is in progress, wait a moment and try again.',
   reconn:'A session already exists for this number, reconnecting.',
   wait:'Generating pairing code...', manual:'Select the code manually',
   generic:'Something went wrong. Please try again shortly.',
   preview:'Will pair:', full:'FULL', off:'OFFLINE', free:'free', linked:'linked accounts',
   auto:'The least busy server was picked for you', none:'No server is online'
 }
};
const M=k=>MSG[lang][k];

function applyLang(){
  document.documentElement.lang=lang==='ur'?'ur':'en';
  document.querySelectorAll('[data-i]').forEach(e=>{
    if(T[lang][e.dataset.i]!==undefined) e.innerHTML=T[lang][e.dataset.i];
  });
  $('langBtn').textContent=lang==='ur'?'EN':'UR';
  setBusy(busy); copyBtn.textContent=M('copy'); regenBtn.textContent=M('regen');
  updatePreview(); renderServers();
  try{localStorage.setItem('rizo_lang',lang)}catch(_){}
}
try{const l=localStorage.getItem('rizo_lang'); if(l==='en'||l==='ur') lang=l}catch(_){}

/* ---------- theme ---------- */
function setTheme(t){
  document.documentElement.dataset.theme=t;
  $('themeBtn').textContent=t==='dark'?'🌙':'☀️';
  document.querySelector('meta[name=theme-color]').content=t==='dark'?'#0f0f10':'#c6c6ca';
  try{localStorage.setItem('rizo_theme',t)}catch(_){}
}
let th='dark'; try{th=localStorage.getItem('rizo_theme')||'dark'}catch(_){}
$('themeBtn').addEventListener('click',()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));

/* ---------- steps ---------- */
function setStep(n){
  step=n;
  [1,2,3].forEach(i=>{
    const e=$('st'+i);
    e.classList.toggle('on',i===n);
    e.classList.toggle('done',i<n);
  });
  $('sl1').classList.toggle('on',n>1);
  $('sl2').classList.toggle('on',n>2);
}

/* ---------- servers ---------- */
function fetchT(url,ms){
  const c=new AbortController();
  const t=setTimeout(()=>c.abort(),ms);
  return fetch(url,{signal:c.signal,cache:'no-store',headers:{Accept:'application/json'}})
    .finally(()=>clearTimeout(t));
}
async function loadServerList(){
  let list=null;
  for(const u of ['/api/servers','servers.json']){
    try{
      const r=await fetchT(u,6000);
      if(!r.ok) continue;
      const d=await r.json();
      list=Array.isArray(d)?d:d.servers;
      /* naya format: sirf ek bar url likhein: {"url":"https://...","count":10} */
      if(!Array.isArray(list)&&d&&!Array.isArray(d)&&d.url){
        var n=Math.max(1,Math.min(parseInt(typeof d.servers==='number'?d.servers:d.count,10)||10,30));
        list=Array.from({length:n},function(_,i){return {id:String(i+1),name:'Server '+String(i+1).padStart(2,'0'),url:d.url}});
      }
      if(list&&list.length) break;
    }catch(_){}
  }
  if(!list||!list.length) list=[{name:'Server 01',url:''}];
  servers=list.map((s,i)=>({
    id:String(s.id||i+1),
    name:s.name||('Server '+String(i+1).padStart(2,'0')),
    url:String(s.url||'').replace(/\/+$/,''),
    online:null, active:0, capacity:50, full:false, ms:0
  }));
}
async function probe(s){
  const t0=performance.now();
  if(!s.url||/YOUR-APP/i.test(s.url)||s.url===location.origin){ s.online=false; s.ms=0; return; }
  try{
    const r=await fetchT(s.url+'/api/server-info?server='+encodeURIComponent(s.id),6000);
    if(!r.ok) throw 0;
    const d=await r.json();
    s.online=true;
    s.active=+d.active||0;
    s.capacity=+d.capacity||50;
    s.full=!!d.full||s.active>=s.capacity;
  }catch(_){
    try{
      const r=await fetchT(s.url+'/ping',6000);
      if(!r.ok) throw 0;
      const d=await r.json();
      if(!d||d.status!=='active') throw 0;
      s.online=true;
      s.active=+d.activeSessions||0;
      s.capacity=50;
      s.full=s.active>=50;
    }catch(__){s.online=false}
  }
  s.ms=Math.round(performance.now()-t0);
}
const barsOf=s=>!s.online?0:s.ms<350?4:s.ms<800?3:s.ms<1600?2:1;
const usable=s=>s.online&&!s.full;
function bestServer(){
  return servers.filter(usable).sort((a,b)=>a.active/a.capacity-b.active/b.capacity)[0]||null;
}
function ico(){
  return '<svg class="si" viewBox="0 0 24 24" fill="none" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="7" rx="2"/><rect x="3" y="13" width="18" height="7" rx="2"/><path d="M7 7.5h.01M7 16.5h.01"/></svg>';
}
function layoutTree(btns){
  const N=btns.length;
  const cnt=[Math.min(2,N),Math.min(4,Math.max(0,N-2)),Math.max(0,N-6)].filter(c=>c>0);
  let i=0,prev=1;
  cnt.forEach((c,li)=>{
    const lk=document.createElement('div'); lk.className='lk'; lk.setAttribute('role','presentation');
    lk.style.setProperty('--m',Math.max(prev,c)); lk.style.setProperty('--d',(li*.42)+'s'); lk.style.setProperty('--r',((cnt.length-1-li)*.16)+'s');
    for(let k=0;k<prev;k++){const e=document.createElement('i'); e.className='p'; e.style.top=((k+.5)/prev*100)+'%'; lk.appendChild(e);}
    for(let k=0;k<c;k++){const e=document.createElement('i'); e.className='c'; e.style.top=((k+.5)/c*100)+'%'; lk.appendChild(e);}
    const col=document.createElement('div'); col.className='tc t'+(c<=2?1:c<=4?2:3); col.style.setProperty('--d',(li*.42)+'s'); col.style.setProperty('--r',((cnt.length-1-li)*.16)+'s'); col.setAttribute('role','presentation');
    for(let k=0;k<c;k++){const sl=document.createElement('div'); sl.className='tn'; sl.style.setProperty('--k',k); sl.setAttribute('role','presentation'); sl.appendChild(btns[i++]); col.appendChild(sl);}
    srvGrid.appendChild(lk); srvGrid.appendChild(col); prev=c;
  });
}
function renderServers(){
  const on=servers.filter(s=>s.online).length;
  onlineTxt.textContent=on+' online';
  const hOn=$('hintOn'); if(hOn) hOn.textContent=on+'/'+servers.length+' online';
  const linked=servers.reduce((a,s)=>a+(s.online?s.active:0),0);
  $('foot').textContent='PAIRING PORTAL · '+linked+' '+M('linked').toUpperCase();
  if(selected){
    srvTitle.textContent=selected.name;
    srvSub.textContent=selected.active+'/'+selected.capacity+' · '+(selected.capacity-selected.active)+' '+M('free');
  }else{
    srvTitle.textContent=M('selSub');
    srvSub.textContent=T[lang].tapChoose;
  }
  srvGrid.innerHTML='';
  const btns=[];
  servers.forEach((s,ix)=>{
    const b=document.createElement('button');
    b.style.setProperty('--i',ix); b.style.setProperty('--n',servers.length); b.style.setProperty('--p',s.online&&s.capacity?Math.min(1,s.active/s.capacity):0);
    b.type='button'; b.setAttribute('role','option');
    const dis=!usable(s);
    b.className='srv'+(selected===s?' sel':'')+(dis?' dis':'');
    b.setAttribute('aria-selected',selected===s?'true':'false');
    b.innerHTML='<span class="r"></span>'+ico()+'<b></b><span class="cap"></span><span class="bars l'+barsOf(s)+'"><i></i><i></i><i></i><i></i></span>'+(dis?'<span class="badge">'+(s.online?M('full'):M('off'))+'</span>':'');
    b.querySelector('b').textContent=s.name;
    b.querySelector('.cap').textContent=s.online?(s.active+'/'+s.capacity):'—';
    b.addEventListener('click',()=>{
      if(dis) return;
      selected=s; userPicked=true;
      renderServers();
      sxClose();
      if(step<2) setStep(2);
      input.focus({preventScroll:true});
    });
    btns.push(b);
  });
  layoutTree(btns);
  srvNote.textContent=(!userPicked&&selected)?M('auto'):(on===0?M('none'):'');
}
async function refreshServers(){
  await Promise.all(servers.map(probe));
  if(selected&&!usable(selected)){selected=null;userPicked=false}
  if(!selected){const b=bestServer(); if(b) selected=b}
  renderServers();
}
function sxAnim(){
  clearTimeout(window._sxC);
  srvBox.classList.remove('sx-close');
  srvBox.classList.add('sx-anim');
  clearTimeout(window._sxT);
  window._sxT=setTimeout(()=>srvBox.classList.remove('sx-anim'),2300);
}
function sxClose(){
  if(!srvBox.classList.contains('open')||srvBox.classList.contains('sx-close')) return;
  clearTimeout(window._sxT);
  srvBox.classList.remove('sx-anim');
  srvBox.classList.add('sx-close');
  srvHead.setAttribute('aria-expanded','false');
  const still=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;
  clearTimeout(window._sxC);
  window._sxC=setTimeout(()=>srvBox.classList.remove('open','sx-close'),still?0:740);
}
srvHead.addEventListener('click',()=>{
  if(srvBox.classList.contains('open')&&!srvBox.classList.contains('sx-close')){ sxClose(); return; }
  srvBox.classList.add('open');
  srvHead.setAttribute('aria-expanded','true');
  sxAnim();
});

/* ---------- number helpers ---------- */
function normalize(v){
  let n=String(v||'').replace(/\D/g,'');
  if(n.startsWith('00')) n=n.slice(2);
  if(n.startsWith(DEFAULT_CC+'0')&&n.length===DEFAULT_CC.length+11) n=DEFAULT_CC+n.slice(DEFAULT_CC.length+1);
  else if(n.startsWith('0')) n=DEFAULT_CC+n.slice(1);
  return n;
}
const pretty=n=>n?'+'+n.replace(/^(\d{2})(\d{3})(\d+)$/,'$1 $2 $3'):'';
function updatePreview(){
  const n=normalize(input.value);
  preview.innerHTML=n.length>=8?M('preview')+' <b>'+pretty(n)+'</b>':'';
}
function setBusy(b){
  busy=b; go.disabled=b;
  go.classList.toggle('loading',b);
  goText.textContent=b?M('busy'):M('gen');
}

/* ---------- result area ---------- */
function resetState(){
  clearInterval(countdown); clearInterval(poller);
  countdown=poller=null;
  timer.classList.remove('show');
  waiting.classList.remove('show');
  success.classList.remove('show');
  copyBtn.classList.remove('show');
  regenBtn.classList.remove('show');
  howto.classList.remove('show');
  currentCode='';
}
function showMsg(text,cls){
  if(typeof text!=='string'){
    try{ text=(text&&(text.message||text.error||text.details))||JSON.stringify(text) }catch(_){ text=String(text) }
    if(typeof text!=='string') try{ text=JSON.stringify(text) }catch(_){ text='Error' }
  }
  resetState();
  res.className='res'+(cls?' '+cls:'');
  resIdle.style.display='none';
  resCode.style.display='block';
  resCode.textContent=text;
}
function showCode(code){
  resetState();
  currentCode=String(code);
  res.className='res';
  resIdle.style.display='none';
  resCode.style.display='block';
  resCode.innerHTML='';
  const clean=currentCode.replace(/[^A-Za-z0-9]/g,'');
  const chars=clean.length===8?(clean.slice(0,4)+'-'+clean.slice(4)).split(''):currentCode.split('');
  const w=document.createElement('div');
  w.className='tiles'; w.setAttribute('aria-label',currentCode);
  chars.forEach((c,i)=>{
    const d=document.createElement('div');
    d.className='tile'+(c==='-'?' dash':'');
    d.textContent=c;
    d.style.animationDelay=(i*45)+'ms';
    w.appendChild(d);
  });
  resCode.appendChild(w);
  copyBtn.textContent=M('copy');
  copyBtn.classList.remove('done');
  copyBtn.classList.add('show');
  howto.classList.add('show');
  waiting.classList.add('show');
  setStep(3);
  startCountdown();
  startPolling();
}
function startCountdown(){
  let left=LIFETIME;
  timer.classList.add('show');
  bar.classList.remove('low');
  timerLabel.textContent=M('expires');
  barFill.style.transition='none'; paint(); void barFill.getBoundingClientRect(); barFill.style.transition='';
  countdown=setInterval(()=>{
    left--; paint();
    if(left<=0){clearInterval(countdown); onExpire()}
  },1000);
  function paint(){
    timeLeft.textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');
    barFill.style.strokeDashoffset=(RING*(1-Math.max(0,left)/LIFETIME)).toFixed(2);
    bar.classList.toggle('low',left<=30);
  }
}
function onExpire(){
  clearInterval(poller);
  waiting.classList.remove('show');
  copyBtn.classList.remove('show');
  regenBtn.textContent=M('regen');
  regenBtn.classList.add('show');
  timeLeft.textContent='0:00';
  timerLabel.textContent=M('expired');
}
function startPolling(){
  clearInterval(poller);
  let tries=0;
  poller=setInterval(async()=>{
    if(++tries>60){clearInterval(poller);return}
    try{
      const r=await fetchT(pollBase+'/status?number='+encodeURIComponent(pollNumber),6000);
      const d=await r.json();
      if(d&&d.isConnected) onConnected();
    }catch(_){}
  },3000);
}
function onConnected(){
  clearInterval(poller); clearInterval(countdown);
  res.style.display='none';
  howto.classList.remove('show');
  waiting.classList.remove('show');
  success.classList.add('show');
  step=4;
  [1,2,3].forEach(i=>{
    $('st'+i).classList.remove('on');
    $('st'+i).classList.add('done');
  });
  $('sl1').classList.add('on');
  $('sl2').classList.add('on');
  try{if(navigator.vibrate) navigator.vibrate([60,40,60])}catch(_){}
  refreshServers();
}
function bad(){
  field.classList.remove('bad');
  void field.offsetWidth;
  field.classList.add('bad');
}

/* ---------- request code ---------- */
async function getCode(){
  if(busy) return;
  res.style.display=''; success.classList.remove('show');
  if(!selected){
    srvBox.classList.add('open'); sxAnim();
    srvHead.setAttribute('aria-expanded','true');
    showMsg(servers.every(function(x){return !x.url||/YOUR-APP/i.test(x.url)||x.url===location.origin})
      ? 'servers.json mein Railway bot ka link nahi hai. YOUR-APP.up.railway.app ki jagah apna link likhein.'
      : M('pick'),'err'); return;
  }
  const num=normalize(input.value);
  if(!num){bad(); showMsg(M('needNum'),'err'); input.focus(); return}
  if(num.length<8||num.length>15){bad(); showMsg(M('badLen'),'err'); input.focus(); return}
  try{localStorage.setItem('rizo_last',num)}catch(_){}
  pollNumber=num; pollBase=selected.url;
  if(step<2) setStep(2);
  setBusy(true);
  showMsg(M('wait'),'wait');
  try{
    const r=await fetchT(pollBase+'/code?'+new URLSearchParams({number:num,server:selected.id}).toString(),45000);
    let d; try{d=await r.json()}catch(_){throw new Error('json')}
    if(d.code) showCode(d.code);
    else if(d.status==='already_connected') onConnected();
    else if(!r.ok){
      showMsg(d.message||d.error||d.details||M('generic'),'err');
      if(d.error==='server_full'){selected.full=true; selected=null; userPicked=false; refreshServers()}
    }
    else showMsg(M({connection_in_progress:'progress',reconnecting:'reconn'}[d.status]||'generic'),'err');
  }catch(e){
    showMsg(M('conn'),'err');
    refreshServers();
  }finally{setBusy(false)}
}
async function copyCode(){
  if(!currentCode) return;
  try{
    if(navigator.clipboard&&window.isSecureContext) await navigator.clipboard.writeText(currentCode);
    else throw 0;
  }catch(_){
    const t=document.createElement('textarea');
    t.value=currentCode; t.setAttribute('readonly','');
    t.style.cssText='position:fixed;opacity:0';
    document.body.appendChild(t); t.select();
    let ok=false; try{ok=document.execCommand('copy')}catch(__){}
    t.remove();
    if(!ok){copyBtn.textContent=M('manual'); return}
  }
  copyBtn.textContent=M('copied');
  copyBtn.classList.add('done');
  setTimeout(()=>{copyBtn.textContent=M('copy'); copyBtn.classList.remove('done')},1800);
}

go.addEventListener('click',getCode);
regenBtn.addEventListener('click',getCode);
copyBtn.addEventListener('click',copyCode);
input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!go.disabled) getCode()});
input.addEventListener('input',()=>{
  input.value=input.value.replace(/[^0-9+\s-]/g,'');
  updatePreview();
});
$('langBtn').addEventListener('click',()=>{lang=lang==='ur'?'en':'ur'; applyLang()});
try{const last=localStorage.getItem('rizo_last'); if(last) input.value=last}catch(_){}
setTheme(th); applyLang(); setStep(1);
(async()=>{
  await loadServerList();
  renderServers();
  await refreshServers();
  if(selected&&step<2) setStep(1);
  setInterval(refreshServers,20000);
})();
})();
;

/* ===== part 3 ===== */
/* ---------- visual effects only ---------- */
(function(){
  var $=function(i){return document.getElementById(i)};
  var reduce=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;

  function mirror(){
    var on=parseInt(($('onlineTxt')||{}).textContent,10)||0;
    var lk=parseInt((($('foot')||{}).textContent||'').replace(/\D/g,''),10)||0;
    if($('stOnline'))$('stOnline').textContent=on;
    if($('stLinked'))$('stLinked').textContent=lk;
    if($('avDot'))$('avDot').classList.toggle('off',on===0);
  }
  ['onlineTxt','foot'].forEach(function(id){
    var e=$(id);
    if(e) new MutationObserver(mirror).observe(e,{childList:true,characterData:true,subtree:true});
  });
  mirror();

  var av=$('avatar'),hero=document.querySelector('.hero');
  if(av&&hero&&!reduce){
    hero.addEventListener('pointermove',function(e){
      var r=av.getBoundingClientRect(),
          x=(e.clientX-(r.left+r.width/2))/(window.innerWidth/2),
          y=(e.clientY-(r.top+r.height/2))/(window.innerHeight/2);
      av.style.setProperty('--ry',(Math.max(-1,Math.min(1,x))*16).toFixed(1)+'deg');
      av.style.setProperty('--rx',(Math.max(-1,Math.min(1,y))*-12).toFixed(1)+'deg');
    });
    hero.addEventListener('pointerleave',function(){
      av.style.setProperty('--rx','0deg');
      av.style.setProperty('--ry','0deg');
    });
  }

  var cv=$('fx');
  if(!cv||reduce) return;
  var cx=cv.getContext('2d'),
      W=0,H=0,dpr=Math.min(window.devicePixelRatio||1,2),
      P=[],C=[],raf=0;

  function size(){
    W=innerWidth; H=innerHeight;
    cv.width=W*dpr; cv.height=H*dpr;
    cx.setTransform(dpr,0,0,dpr,0,0);
    var n=0;
    P=[];
    for(var i=0;i<n;i++)
      P.push({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.38,vy:(Math.random()-.5)*.38,r:Math.random()*1.7+.6});
  }
  size();
  addEventListener('resize',size);

  function light(){return document.documentElement.dataset.theme==='light'}

  function frame(){
    if(!P.length&&!C.length){cx.clearRect(0,0,W,H);raf=0;return}
    cx.clearRect(0,0,W,H);
    var lt=light(),
        dot=lt?'79,107,255':'160,200,255',
        ln=lt?'79,107,255':'110,170,255';

    for(var i=0;i<P.length;i++){
      var p=P[i];
      p.x+=p.vx; p.y+=p.vy;
      if(p.x<0||p.x>W)p.vx*=-1;
      if(p.y<0||p.y>H)p.vy*=-1;
      cx.beginPath(); cx.arc(p.x,p.y,p.r,0,6.283);
      cx.fillStyle='rgba('+dot+','+(lt?.5:.78)+')'; cx.fill();
      for(var j=i+1;j<P.length;j++){
        var q=P[j],dx=p.x-q.x,dy=p.y-q.y,d=dx*dx+dy*dy;
        if(d<13000){
          cx.strokeStyle='rgba('+ln+','+((1-d/13000)*(lt?.20:.32)).toFixed(3)+')';
          cx.lineWidth=.7;
          cx.beginPath(); cx.moveTo(p.x,p.y); cx.lineTo(q.x,q.y); cx.stroke();
        }
      }
    }
    for(var k=C.length-1;k>=0;k--){
      var c=C[k];
      c.vy+=.12; c.vx*=.992; c.x+=c.vx; c.y+=c.vy; c.rot+=c.vr; c.life--;
      if(c.life<=0||c.y>H+20){C.splice(k,1); continue}
      cx.save(); cx.translate(c.x,c.y); cx.rotate(c.rot);
      cx.globalAlpha=Math.min(1,c.life/40);
      cx.fillStyle=c.col;
      cx.fillRect(-c.w/2,-c.h/2,c.w,c.h);
      cx.restore();
    }
    raf=requestAnimationFrame(frame);
  }
  function start(){if(!raf&&!document.hidden) raf=requestAnimationFrame(frame)}
  document.addEventListener('visibilitychange',function(){
    if(document.hidden){cancelAnimationFrame(raf);raf=0}
    else start();
  });
  start();

  function burst(){
    var cols=['#ff9a3d','#ff5fa8','#8d6bf0','#3aa0ff','#2ecf8f','#ffd24a','#ffffff'];
    for(var i=0;i<130;i++){
      var a=Math.random()*Math.PI-Math.PI, s=Math.random()*9+4;
      C.push({
        x:W/2, y:H*.35,
        vx:Math.cos(a)*s*(Math.random()+.4),
        vy:Math.sin(a)*s-2,
        w:Math.random()*7+4, h:Math.random()*4+2,
        rot:Math.random()*6, vr:(Math.random()-.5)*.4,
        col:cols[i%cols.length],
        life:110+Math.random()*60
      });
    }
    start();
  }
  var sc=$('success');
  if(sc){
    var was=false;
    new MutationObserver(function(){
      var on=sc.classList.contains('show');
      if(on&&!was) burst();
      was=on;
    }).observe(sc,{attributes:true,attributeFilter:['class']});
  }
})();
;

