(function(){
  var a=document.getElementById('bgm'), ld=document.getElementById('ldMusic'), mf=document.getElementById('mfBtn'), en=document.getElementById('ldEnter');
  if(!a||!mf) return;
  var want=true, resume=false;
  a.volume=.85;
  function ui(){
    var on=!a.paused;
    mf.classList.toggle('off',!on); mf.setAttribute('aria-pressed',on);
    if(ld){ ld.classList.toggle('off',!want); ld.setAttribute('aria-pressed',want); }
  }
  function play(){ var r=a.play(); if(r&&r.catch) r.catch(function(){ want=false; ui(); }); }
  a.addEventListener('play',ui); a.addEventListener('pause',ui);
  if(ld) ld.addEventListener('click',function(){ want=!want; if(want) play(); else a.pause(); ui(); });
  if(en) en.addEventListener('click',function(){ if(want) play(); });
  mf.addEventListener('click',function(){ if(a.paused){ want=true; play(); } else { want=false; a.pause(); } ui(); });
  document.addEventListener('visibilitychange',function(){
    if(document.hidden){ resume=!a.paused; a.pause(); } else if(resume){ resume=false; play(); }
  });
  ui();
})();
;

