function audio(b){
  var a=el('div','pv-au'),p=el('div','pv-pl','▶'),w=el('div','pv-wv'),tm=el('small',0,'0:24'),bars=[],i;
  p.setAttribute('role','button');p.setAttribute('aria-label','Play');p.tabIndex=0;
  for(i=0;i<24;i++){var s=el('i');s.style.height=(5+Math.abs(Math.sin(i*1.3))*18)+'px';bars.push(s);w.appendChild(s)}
  a.appendChild(p);a.appendChild(w);a.appendChild(tm);b.appendChild(a);
  var au=CFG.audio?new Audio():null,dur=24,pos=0,sim=null,on=false;
  function paint(f){var n=Math.round(f*bars.length);bars.forEach(function(x,j){x.className=j<n?'o':''})}
  function stop(){on=false;p.textContent='▶';clearInterval(sim);if(au)au.pause()}
  function reset(){stop();pos=0;paint(0);tm.textContent=fmt(dur)}
  if(au){au.preload='metadata';au.src=CFG.audio;
    au.addEventListener('loadedmetadata',function(){dur=au.duration;tm.textContent=fmt(dur)});
    au.addEventListener('timeupdate',function(){paint(au.currentTime/(au.duration||1));tm.textContent=fmt(au.currentTime)});
    au.addEventListener('ended',function(){au.currentTime=0;reset()});
    au.addEventListener('error',function(){au=null;reset()})}
  function tog(){
    if(on){stop();return}
    on=true;p.textContent='❚❚';
    if(au){var pr=au.play();if(pr&&pr.catch)pr.catch(function(){stop()})}
    else{sim=setInterval(function(){pos+=.2;if(pos>=dur){reset();return}paint(pos/dur);tm.textContent=fmt(pos)},200)}
  }
  p.addEventListener('click',tog);
  p.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();tog()}});
  reset();CL.push(stop);
}
