/* ===== smooth-scroll-pro (JS) ===== */
(function(){
  var d=document,w=window,root=d.documentElement;
  var reduce=w.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* progress bar */
  var bar=d.createElement('div');bar.id='spBar';d.body.appendChild(bar);

  var tick=0,idle=0;
  function frame(){
    tick=0;
    var y=w.pageYOffset||root.scrollTop,h=root.scrollHeight-w.innerHeight;
    bar.style.transform='scaleX('+(h>0?Math.min(1,y/h):0)+')';
  }
  w.addEventListener('scroll',function(){
    if(!tick)tick=requestAnimationFrame(frame);
    root.classList.add('is-scrolling');
    clearTimeout(idle);idle=setTimeout(function(){root.classList.remove('is-scrolling')},140);
  },{passive:true});
  frame();

  /* sections scroll karte hi halke se andar aayen */
  if(!reduce&&'IntersectionObserver' in w){
    var els=d.querySelectorAll('.howto,.cut.cm,.cut.cmd,.about,.footer');
    var io=new IntersectionObserver(function(es){
      es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}})
    },{rootMargin:'0px 0px -8% 0px',threshold:.06});
    els.forEach(function(el){el.classList.add('rv');io.observe(el)});
  }

  /* desktop mouse-wheel inertia (touch/trackpad ko haath nahi lagate) */
  var fine=w.matchMedia&&matchMedia('(hover:hover) and (pointer:fine)').matches;
  if(reduce||!fine)return;
  var target=0,cur=0,run=false,EASE=.11;
  function canScroll(el){
    while(el&&el!==d.body&&el!==root){
      var cs=getComputedStyle(el),oy=cs.overflowY;
      if((oy==='auto'||oy==='scroll')&&el.scrollHeight>el.clientHeight+1)return true;
      el=el.parentElement;
    }
    return false;
  }
  function loop(){
    var diff=target-cur;
    if(Math.abs(diff)<.4){cur=target;w.scrollTo(0,cur);run=false;return}
    cur+=diff*EASE;w.scrollTo(0,cur);requestAnimationFrame(loop);
  }
  w.addEventListener('wheel',function(e){
    if(e.ctrlKey||e.defaultPrevented||e.deltaX&&Math.abs(e.deltaX)>Math.abs(e.deltaY))return;
    if(e.deltaMode===0&&Math.abs(e.deltaY)<50)return; /* trackpad: pehle se smooth hai */
    if(canScroll(e.target)||d.querySelector('.modal.show'))return;
    e.preventDefault();
    var max=root.scrollHeight-w.innerHeight;
    if(!run)cur=target=w.pageYOffset;
    var dy=e.deltaMode===1?e.deltaY*32:e.deltaY;
    target=Math.max(0,Math.min(max,target+dy));
    if(!run){run=true;requestAnimationFrame(loop)}
  },{passive:false});
  /* keyboard/scrollbar se scroll ho to sync rakhein */
  w.addEventListener('scroll',function(){if(!run){cur=target=w.pageYOffset}},{passive:true});
})();
;

